        return true;
    }
    if (n == 0) {
        deallocate(p, data, max_size, b);
        return true;
    }
    if (!b) {
        b = allocate(p, data, max_size, alignment, n);
        return true;
    }
    const auto alignedLength = internal::round_to_alignment(alignment, n);
    if (is_last_used_block(p, data, b)) {
        if (static_cast<char *>(b.ptr) + alignedLength <= data + max_size) {
            b.length = alignedLength;
            p = static_cast<char *>(b.ptr) + alignedLength;
            return true;
        }
        return false;
    }
    if (b.length > n) {
        b.length = internal::round_to_alignment(alignment, n);
        return true;
    }
    auto newBlock = allocate(p, data, max_size, alignment, alignedLength);
    if (newBlock) {
        internal::block_copy(b, newBlock);
        b = newBlock;
        return true;
    }
    return false;

